queries.content:
query RefreshMarketMatrix($after: String) {
 shop { id }
 markets(first: 10, after: $after) {
  nodes {
   id name handle status type
   conditions {
    conditionTypes
    regionsCondition {
     applicationLevel
     regions(first: 250) {
      nodes { __typename ... on MarketRegionCountry { id code name currency { currencyCode enabled } } }
      pageInfo { hasNextPage endCursor }
     }
    }
   }
   currencySettings { baseCurrency { currencyCode enabled } localCurrencies roundingEnabled }
   webPresences(first: 10) {
    nodes {
     id
     domain { id host url localization { country defaultLocale alternateLocales } }
     subfolderSuffix
     defaultLocale { locale published }
     alternateLocales { locale published }
     rootUrls { locale url }
    }
    pageInfo { hasNextPage endCursor }
   }
   catalogsCount { count precision }
   catalogs(first: 10) {
    nodes { id title status priceList { id name currency fixedPricesCount } publication { id autoPublish includedProductsCount(query: "status:active") { count precision } } }
    pageInfo { hasNextPage endCursor }
   }
  }
  pageInfo { hasNextPage endCursor }
 }
}

query RefreshShopMarketBindings($after: String) {
 shop {
  id name currencyCode enabledPresentmentCurrencies
  countriesInShippingZones { countryCodes includeRestOfWorld }
  shipsToCountries
  primaryDomain {
   id host url localization { country defaultLocale alternateLocales }
   marketWebPresence {
    id domain { id host url } subfolderSuffix
    defaultLocale { locale published }
    alternateLocales { locale published }
    rootUrls { locale url }
    markets(first: 50) { nodes { id name status } pageInfo { hasNextPage endCursor } }
   }
  }
 }
 shopLocales { locale name primary published marketWebPresences { id } }
 publications(first: 50, after: $after) {
  nodes {
   id autoPublish includedProductsCount(query: "status:active") { count precision }
   catalog { id title status __typename ... on AppCatalog { apps(first: 10) { nodes { id title } pageInfo { hasNextPage endCursor } } } }
  }
  pageInfo { hasNextPage endCursor }
 }
 productsCount(query: "status:active") { count precision }
}

query ResolveFiveCountryMarkets($c1: CountryCode!, $c2: CountryCode!, $c3: CountryCode!, $c4: CountryCode!, $c5: CountryCode!) {
 shop { id }
 c1: marketsResolvedValues(buyerSignal: {countryCode: $c1}) { ...Resolution }
 c2: marketsResolvedValues(buyerSignal: {countryCode: $c2}) { ...Resolution }
 c3: marketsResolvedValues(buyerSignal: {countryCode: $c3}) { ...Resolution }
 c4: marketsResolvedValues(buyerSignal: {countryCode: $c4}) { ...Resolution }
 c5: marketsResolvedValues(buyerSignal: {countryCode: $c5}) { ...Resolution }
}
fragment Resolution on MarketsResolvedValues {
 currencyCode
 catalogs(first: 10) {
  nodes { id title status publication { id autoPublish } }
  pageInfo { hasNextPage endCursor }
 }
 webPresences(first: 10) {
  nodes {
   id domain { id host url } subfolderSuffix
   defaultLocale { locale published }
   alternateLocales { locale published }
   rootUrls { locale url }
  }
  pageInfo { hasNextPage endCursor }
 }
}
